var result=JsonUtility.FromJson<RoadResult>(File.ReadAllText("Tools/SurfaceZones/surface_zone_result.json"));var vertices=new List<Vector3>();var indices=new List<int>[6];for(int i=0;i<6;i++)indices[i]=new List<int>();foreach(var layer in result.layers)for(int j=0;j<layer.xy.Length;j+=6){int n=vertices.Count;for(int k=0;k<3;k++)vertices.Add(new Vector3(layer.xy[j+k*2],.014f,layer.xy[j+k*2+1]));indices[layer.channel].AddRange(new[]{n,n+2,n+1});}var mesh=new Mesh{name="FunctionalSurfaceZones",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(vertices);mesh.subMeshCount=6;for(int i=0;i<6;i++)mesh.SetTriangles(indices[i],i);mesh.RecalculateNormals();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,folder+"/FunctionalSurfaceZones.asset");var root=new GameObject("Ground_FunctionalSurfaceZones");root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=materials;
var verge=new GameObject("BoundaryScreeningTrees");verge.transform.SetParent(root.transform);var tree=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Anseong/Art/Environment/Assets/ScreeningTrees/ScreeningTree_B.prefab");int trees=0;for(int i=0;i<24;i++){float x=i<14?-607:-857;float z=i<14?-235+i*46:490+(i-14)*48;var g=(GameObject)PrefabUtility.InstantiatePrefab(tree);g.transform.SetParent(verge.transform,false);g.transform.position=new Vector3(x,0,z);g.transform.rotation=Quaternion.Euler(0,i*37%360,0);foreach(var col in g.GetComponentsInChildren<Collider>())col.enabled=false;trees++;}File.WriteAllText(folder+"/ZoneGuide.md",result.report+"\n\nMaterials01–06 are independently replaceable and share the same compressed1024 concrete-grain texture. Production dark paving, warehouse dispatch light concrete, three container heavy-duty pads, quay concrete band, central shared haul yard, unpaved maintenance verge. Patch vertices Y0.014 below roadY0.038, base meshes unchanged.24 existing2.6m screening trees reused on outer maintenance verge, colliders disabled. No real-time decals, reflections, added physics or terrain system. Shading/material differences are a first visual pass; VR performance unmeasured.\n");AssetDatabase.Refresh();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),Scene);Capture(Camera.main,"SurfaceZones_Main");var go=new GameObject("SurfaceZonesPreview");var camera=go.AddComponent<Camera>();camera.CopyFrom(Camera.main);camera.transform.position=new Vector3(80,100,-300);camera.transform.LookAt(new Vector3(40,0,-100));Capture(camera,"SurfaceZones_Yard");camera.transform.position=new Vector3(50,115,250);camera.transform.LookAt(new Vector3(190,0,150));Capture(camera,"SurfaceZones_Quay");Object.DestroyImmediate(go);Debug.Log("SURFACE_ZONES_PASS materials=6 textureShared=true extraGroundRenderer=1 trees="+trees+" roadClearance=true");}
